#!/usr/bin/env bash
# Prints Casks/lysosome-app.rb for a promoted build of the lysosome desktop app.
#
#   render-cask.sh           # the build lysosome.dev/download currently serves
#   render-cask.sh 0.2.0     # a specific version
#
# lysosome.dev publishes no checksum file for the app, so both DMGs are
# downloaded and hashed. Needs: curl, jq, shasum.
set -euo pipefail

SITE="https://lysosome.dev"
VERSION="${1:-}"

if [ -z "$VERSION" ]; then
  VERSION="$(curl -fsSL --retry 3 "$SITE/app/downloads.json" | jq -r .version)"
fi
if ! [[ "$VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+([-.+][0-9A-Za-z.-]+)?$ ]]; then
  echo "error: unexpected version '$VERSION'" >&2
  exit 1
fi

# Fail loudly if the release's file names ever stop matching the cask's url.
MANIFEST="$(curl -fsSL --retry 3 "$SITE/app/releases/$VERSION/downloads.json")"
for pair in "mac:aarch64" "mac-intel:x64"; do
  key="${pair%%:*}" want="lysosome_${VERSION}_${pair#*:}.dmg"
  got="$(printf '%s' "$MANIFEST" | jq -r --arg k "$key" '.files[$k] // empty')"
  if [ "$got" != "$want" ]; then
    echo "error: $VERSION downloads.json has files.$key='$got', expected '$want'" >&2
    exit 1
  fi
done

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

sha() {
  local file="lysosome_${VERSION}_$1.dmg"
  curl -fsSL --retry 3 -o "$TMP/$file" "$SITE/app/releases/$VERSION/$file"
  shasum -a 256 "$TMP/$file" | awk '{ print $1 }'
}

ARM="$(sha aarch64)"
INTEL="$(sha x64)"

cat <<RUBY
# The lysosome desktop app (free beta). Generated by
# .github/workflows/update-cask.yml from the $VERSION build on lysosome.dev.
# Do not edit by hand; change .github/scripts/render-cask.sh instead.
cask "lysosome-app" do
  arch arm: "aarch64", intel: "x64"

  version "$VERSION"
  sha256 arm:   "$ARM",
         intel: "$INTEL"

  url "https://lysosome.dev/app/releases/#{version}/lysosome_#{version}_#{arch}.dmg"
  name "lysosome"
  desc "Find and safely reclaim disk space left behind by dev tools and coding agents"
  homepage "https://lysosome.dev/"

  livecheck do
    url "https://lysosome.dev/app/downloads.json"
    strategy :json do |json|
      json["version"]
    end
  end

  auto_updates true
  depends_on formula: "lysosome-dev/tap/lysosome"
  depends_on :macos

  app "lysosome.app"

  zap trash: [
    "~/Library/Application Support/dev.lysosome.app",
    "~/Library/Caches/dev.lysosome.app",
    "~/Library/Logs/dev.lysosome.app",
    "~/Library/Preferences/dev.lysosome.app.plist",
    "~/Library/Saved Application State/dev.lysosome.app.savedState",
    "~/Library/WebKit/dev.lysosome.app",
  ]
end
RUBY
